    /// <summary>
    /// MPJ_24809 Returns Claims
    /// Service method to get Return order created
    /// </summary>
    /// <param name="dataAreaId"> Get company id</param>
    /// <param name="customerAccountNumber"> Get customer Account Number</param>
    /// <param name="reasonCode"> Get reason Code</param>
    /// <param name="invoiceNumber"> Get invoice Number</param>
    /// <param name="parentClaimId"> Get parent Claim Id"</param>
    [
        SysODataActionAttribute('CreateReturnOrder',false),
        SysODataCollectionAttribute("dataAreaId", Types::String),
        SysODataCollectionAttribute("customerAccountNumber", Types::String),
        SysODataCollectionAttribute("reasonCode", Types::String),
        SysODataCollectionAttribute("invoiceNumber", Types::String),
        SysODataCollectionAttribute("parentClaimId", Types::String),
        SysODataCollectionAttribute("return", Types::Record, 'METSalesTableEntity')
        
    ]
    public static List createReturnOrder(DataAreaId dataAreaId,
                                         CustAccount customerAccountNumber,
                                         METClaimReason reasonCode,
                                         METInvoiceNumber invoiceNumber,
                                         METParentClaimId parentClaimId
                                            )
    {
        SalesTable          metSalesTableStdReturn;
        METSalesTable       metSalesTable;
        METSalesTableEntity metSalesTableEntity;
        List                metSalesTableEntityList = new List(Types::Record);
        changecompany(dataAreaId)
        {
             ttsbegin;
            metSalesTableStdReturn.initValue();
            metSalesTableStdReturn.CustAccount          = customerAccountNumber;
            metSalesTableStdReturn.initFromCustTable();
            metSalesTableStdReturn.CustInvoiceId        = invoiceNumber;
            metSalesTableStdReturn.ReturnReasonCodeId   = reasonCode;
            metSalesTableStdReturn.SalesType            = SalesType::ReturnItem;
            metSalesTableStdReturn.SalesId              = NumberSeq::newGetNum(SalesParameters::numRefSalesId()).num();
            metSalesTableStdReturn.ReturnItemNum        = NumberSeq::newGetNum(SalesParameters::numRefReturnItemNum()).num();
            metSalesTableStdReturn.ReturnStatus         = ReturnStatusHeader::Created;
            metSalesTableStdReturn.insert();

            metSalesTable = METSalesTable::findByRefRecId(metSalesTableStdReturn.RecId);
            if(!metSalesTable && metSalesTableStdReturn)
            {
                metSalesTable.SalesTable        = metSalesTableStdReturn.RecId;
                metSalesTable.SalesId           = metSalesTableStdReturn.SalesId;
                metSalesTable.ParentClaimId     = parentClaimId;
                metSalesTable.OriginalInvoice   = invoiceNumber;
                metSalesTable.ClaimReason       = reasonCode;
                metSalesTable.insert();
            }
            else
            {
                metSalesTable.selectForUpdate(true);
                metSalesTable.ParentClaimId     = parentClaimId;
                metSalesTable.ClaimReason       = reasonCode;
                metSalesTable.OriginalInvoice   = invoiceNumber;
                metSalesTable.update();
            }
            ttscommit;
            
            
            select metSalesTableEntity
                where metSalesTableEntity.SalesTableSalesId == metSalesTableStdReturn.SalesId;
            
            metSalesTableEntityList.addEnd(metSalesTableEntity);

            
        }       
               
        return metSalesTableEntityList;
    }

    /// <summary>
    /// MPJ_24809 Returns Claims
    /// Service method to get Return order created
    /// </summary>
    /// <param name="dataAreaId"> Get company id</param>    
    /// <param name="reasonCode"> Get reason Code</param>
    /// <param name="RMANumber"> Get RMA Number</param>
    /// <param name="returnStatus"> Get return Status"</param>
    [
        SysODataActionAttribute('UpdateReturnOrderHeaderStatus',false),   
        SysODataCollectionAttribute("dataAreaId", Types::String),
        SysODataCollectionAttribute("reasonCode", Types::String),
        SysODataCollectionAttribute("RMANumber", Types::String),
        SysODataCollectionAttribute("returnStatus", Types::String)
    ]
    public static void updateReturnOrderHeaderStatus (DataAreaId dataAreaId,                                        
                                                     METClaimReason reasonCode,
                                                     SalesReturnItemNum RMANumber,
                                                     string20 returnStatus
                                            )
    {
        changecompany(dataAreaId)
        {
            SalesTable   metSalesTableStd = SalesTable::findReturnItemNum(RMANumber);
            if(metSalesTableStd)
            {
                METSalesTable   metSalesTable   = METSalesTable::findByRefRecId(metSalesTableStd.RecId);
                METReturnStatus metReturnStatus;
                ttsbegin;
                metSalesTable.selectForUpdate(true);
                metSalesTable.ReturnStatus  = str2Enum(metReturnStatus, returnStatus);
                metSalesTable.ClaimReason   = reasonCode;
                metSalesTable.update();
                if(metSalesTable.ReturnStatus == METReturnStatus::Rejected)
                {
                    METSalesTableEntity::returnCancel(metSalesTableStd);
                }
                

                ttscommit;

            }
        }
    }

    /// <summary>
    /// MPJ_24809 Returns Claims
    /// Service method to get Return order line return disposition code updated
    /// </summary>
    /// <param name="dataAreaId"> Get company id</param>    
    /// <param name="RMANumber"> Get RMA Number</param>
    /// <param name="returnDispositionCode"> Get return disposition code"</param>
    /// <param name="metInvoiceLineNumber"> Get metcash invoice line number</param>
    [
        SysODataActionAttribute('UpdateReturnOrderLineReturnDispositionCode',false),
        SysODataCollectionAttribute("dataAreaId", Types::String),        
        SysODataCollectionAttribute("RMANumber", Types::String),
        SysODataCollectionAttribute("returnDispositionCode", Types::String),
        SysODataCollectionAttribute("metInvoiceLineNumber", Types::Real)
    ]
    public static void updateReturnOrderLineReturnDispositionCode (DataAreaId dataAreaId,                                         
                                                     SalesReturnItemNum RMANumber,
        ReturnDispositionCodeId returnDispositionCode,
                                                     METInvoiceLineNumber metInvoiceLineNumber
                                            )
    {
        changecompany(dataAreaId)
        {
            SalesTable      metSalesTableStd;
            SalesLine       metSalesLineStd;
            METSalesLine    metSalesLine;
            
            select firstonly metSalesLineStd
                exists join metSalesLine                
                where metSalesLine.SalesLine == metSalesLineStd.RecId &&
                      metSalesLine.InvoiceLineNumber == metInvoiceLineNumber
                exists join metSalesTableStd
                where metSalesTableStd.ReturnItemNum == RMANumber &&
                metSalesTableStd.SalesId  == metSalesLineStd.SalesId;
            if(metSalesLineStd)
            {                
                ttsbegin;
                metSalesLineStd.selectForUpdate(true);
                metSalesLineStd.ReturnDispositionCodeId = returnDispositionCode;
                metSalesLineStd.update();
                ttscommit;

            }
        }
    }

    /// <summary>
    /// MPJ_24809 Returns Claims
    ///  method to get Return order cancelled
    /// </summary>
    /// <param name="_returnTable"> Get return order id</param>    
    public static void returnCancel(SalesTable _returnTable)
    {
        SalesTable          returnTableUpdate;
        MCRSalesOrderCancellation mcrSalesOrderCancellation = new MCRSalesOrderCancellation();
                
        boolean mcrOrderCompletionEnabled = RetailMCRChannelTable::mcrEnableOrderCompletion(_returnTable);
        if (mcrOrderCompletionEnabled)
        {
            
            mcrSalesOrderCancellation.preCancel(_returnTable);
            // %1 return order(s) was cancelled
            //SalesTable::changeReturnStatus(formDataSource, ReturnUpdateAction::Cancel)));            
            SalesLine           returnLine;           
            Counter             numberOfRecords;
            SalesTable          salesTable;
            PurchTable          purchTable;
            PurchLine           purchLine;
            
            while select forupdate returnLine
                          where returnLine.SalesId == _returnTable.SalesId
            {
                if (returnLine.interCompanySalesLineExist())
                {
                    purchLine            = PurchLine::findInventTransId(returnLine.InventRefTransId,true);
                    purchTable           = PurchTable::find(purchLine.PurchId);

                    purchLine.SkipUpdate = InterCompanySkipUpdate::Internal;
                    purchLine.delete(false);

                    if (!purchTable.existPurchLine())
                    {
                        if (purchTable.InterCompanyCompanyId
                                &&  purchTable.InterCompanySalesId)
                        {
                            changecompany(purchTable.InterCompanyCompanyId)
                            {
                                salesTable = null;
                                salesTable = SalesTable::find(purchTable.InterCompanySalesId,true);
                                if (salesTable)
                                            salesTable.delete();
                            }
                        }
                    }
                }

                returnLine.SalesQty            = 0;
                returnLine.CostPrice           = 0;
                returnLine.ExpectedRetQty      = 0;
                returnLine.salesQtyModified();
                returnLine.DeliveryType        = TradeLineDlvType::None;
                returnLine.SourcingOrigin      = SalesSourcingOrigin::Inventory;
                returnLine.SkipUpdate          = InterCompanySkipUpdate::Internal;
                returnLine.ReturnStatus        = ReturnStatusLine::Canceled;   // This assignment is required to make sure that InventPendingQuantity gets cleaned up
                returnLine.SalesStatus         = SalesStatus::Canceled;        // This assignment is required to make sure that InventPendingQuantity gets cleaned up
                returnLine.ReturnClosedDate    = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
                returnLine.InventTransIdReturn = '';
                returnLine.update();
            }
            if (isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter)))
            {
                returnLine.skipDataMethods(true);
                update_recordset returnLine
                        setting          ReturnStatus         = ReturnStatusLine::Canceled,
                                         CostPrice            = 0,
                                         InventTransIdReturn  = '',
                                         SalesStatus          = SalesStatus::Canceled,
                                         ReturnClosedDate     = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())
                        where returnLine.SalesId == _returnTable.SalesId;
            }           
        }
        SpecTransManager::newFromSpec(_returnTable).deleteAll();
        returnTableUpdate = SalesTable::find(_returnTable.SalesId, true);
        returnTableUpdate.ReturnStatus               = ReturnStatusHeader::Canceled;
        returnTableUpdate.SalesStatus                = SalesStatus::Canceled;
        returnTableUpdate.InterCompanyDirectDelivery = false;
        METSalesTableEntity::unlinkAgreement(_returnTable,true, false, false, true);
        returnTableUpdate.update();
        if (_returnTable.SalesStatus == SalesStatus::Canceled)
        {
            mcrSalesOrderCancellation.postCancelOrder(_returnTable);
        }

        mcrSalesOrderCancellation.postCancelAdjPayment(_returnTable);

        
    
    }

    /// <summary>
    /// Unlink agreement on <c>SalesTable</c> record.
    /// </summary> 
    /// </param>
    /// <param name="salesTable">
    /// A <c>SalesTable</c> record.
    /// </param>
    /// <param name="_unlinkLines">
    /// A boolean indicates whether to unlink <c>SalesLine</c> or not.    
    /// </param>
    /// <param name="_recalculatePrice">
    /// A boolean indicates whether to recalculate price or not.
    /// </param>
    /// <param name="_doUpdateSalesTable">
    /// A boolean indicates whether to udpate <c>SalesTable</c> or not.
    /// </param>
    /// <param name="_doUpdateSalesLine">
    /// A boolean indicates whether to udpate <c>SalesLine</c> or not.
    
    public static void unlinkAgreement(SalesTable _salesTable,
                                        boolean _unlinkLines      = false,
                                        boolean _recalculatePrice = false,
                                        boolean _doUpdateSalesTable = true,
                                        boolean _doUpdateSalesLine  = true
                                        )
    {
        AgreementReleaseHeaderMatch agreementReleaseHeaderMatch;
        SalesLine                   salesLine;
        boolean                     restorePriceDiscChagnePolicy = true;
        SalesTable_RU               salesTableRU;

        #ISOCountryRegionCodes

        if (_salesTable.MatchingAgreement)
        {
            ttsbegin;

            if (_unlinkLines)
            {
                while select forupdate salesLine
                        where salesLine.SalesId == _salesTable.SalesId
                {
                    METSalesTableEntity::unlinkAgreementOnSalesLine(salesLine, _recalculatePrice, _doUpdateSalesLine);
                }
            }

            delete_from agreementReleaseHeaderMatch
            where agreementReleaseHeaderMatch.SalesTableSalesId == _salesTable.SalesId
               && agreementReleaseHeaderMatch.SalesTableDataAreaId == _salesTable.DataAreaId;

            _salesTable.MatchingAgreement = 0;

            if (SysCountryRegionCode::isLegalEntityInCountryRegion([#isoRU]))
            {
                salesTableRU = _salesTable.salesTable_RU();
                salesTableRU.AgreementHeaderExt_RU = 0;
                _salesTable.packSalesTable_RU(salesTableRU);

                _salesTable.DefaultDimension = AgreementHeaderExt_RU::clearAgreementDimension(_salesTable.DefaultDimension);
            }

            if (_doUpdateSalesTable)
            {
                _salesTable.doUpdate();
            }
            ttscommit;
        }
    }

    /// <summary>
    /// Unlink agreement on <c>SalesLine</c> record.
    /// </summary>
    /// <param name="_salesLine">
    /// A <c>SalesLine</c> record.
    /// </param>
    /// <param name="_recalculatePrice">
    /// A boolean indicates whether to recalculate price or not.
    /// </param>
    /// <param name="_doUpdateSalesLine">
    /// A boolean indicates whether to udpate <c>SalesLine</c> or not.
    /// </param>
    public static void unlinkAgreementOnSalesLine(SalesLine _salesLine, boolean _recalculatePrice, boolean _doUpdateSalesLine)
    {
        if (_salesLine.MatchingAgreementLine)
        {
            if (_recalculatePrice)
            {
                SalesLine::modifySalesQty(_salesLine,_salesLine.inventDim());
            }
            else
            {
                // Set Price Discount Change Policy originated by PriceDiscSystemSource::Agreement.
                _salesLine.setPriceDiscChangePolicy(PriceDiscSystemSource::Agreement);
            }

            _salesLine.unLinkAgreementLine(_doUpdateSalesLine);
        }
    }
